define(["jquery","core/str","core/notification"],function($,Str,Notification){const selectors={root:"[data-region='ohmslaw-calculator']",input:"[data-value]",status:"[data-region='status']",results:"[data-region='results']",calculations:"[data-region='calculations']",relations:"[data-region='relations']",extras:"[data-region='extras']",clear:"[data-action='clear']"};const units={voltage:"V",current:"A",resistance:"Ω",power:"W"};const symbols={voltage:"V",current:"I",resistance:"R",power:"P"};const escapeHtml=function(value){return $("<div>").text(value).html()};const formatNumber=function(value){if(!Number.isFinite(value)){return"-"}const absolute=Math.abs(value);if(absolute!==0&&absolute<1e-4||absolute>=1e6){return value.toExponential(6).replace(/\.?0+e/,"e")}return Number(value.toPrecision(8)).toLocaleString(undefined,{maximumFractionDigits:8})};const formatValue=function(value,unit){return formatNumber(value)+" "+unit};const solve=function(values){let v=values.voltage;let i=values.current;let r=values.resistance;let p=values.power;let steps=[];if(v!==null&&i!==null){r=v/i;p=v*i;steps=[{formula:"R = V ÷ I",expression:`R = ${formatNumber(v)} ÷ ${formatNumber(i)}`,result:formatValue(r,"Ω")},{formula:"P = V × I",expression:`P = ${formatNumber(v)} × ${formatNumber(i)}`,result:formatValue(p,"W")}]}else if(v!==null&&r!==null){i=v/r;p=v*v/r;steps=[{formula:"I = V ÷ R",expression:`I = ${formatNumber(v)} ÷ ${formatNumber(r)}`,result:formatValue(i,"A")},{formula:"P = V² ÷ R",expression:`P = ${formatNumber(v)}² ÷ ${formatNumber(r)}`,result:formatValue(p,"W")}]}else if(v!==null&&p!==null){i=p/v;r=v*v/p;steps=[{formula:"I = P ÷ V",expression:`I = ${formatNumber(p)} ÷ ${formatNumber(v)}`,result:formatValue(i,"A")},{formula:"R = V² ÷ P",expression:`R = ${formatNumber(v)}² ÷ ${formatNumber(p)}`,result:formatValue(r,"Ω")}]}else if(i!==null&&r!==null){v=i*r;p=i*i*r;steps=[{formula:"V = I × R",expression:`V = ${formatNumber(i)} × ${formatNumber(r)}`,result:formatValue(v,"V")},{formula:"P = I² × R",expression:`P = ${formatNumber(i)}² × ${formatNumber(r)}`,result:formatValue(p,"W")}]}else if(i!==null&&p!==null){v=p/i;r=p/(i*i);steps=[{formula:"V = P ÷ I",expression:`V = ${formatNumber(p)} ÷ ${formatNumber(i)}`,result:formatValue(v,"V")},{formula:"R = P ÷ I²",expression:`R = ${formatNumber(p)} ÷ ${formatNumber(i)}²`,result:formatValue(r,"Ω")}]}else if(r!==null&&p!==null){i=Math.sqrt(p/r);v=Math.sqrt(p*r);steps=[{formula:"I = √(P ÷ R)",expression:`I = √(${formatNumber(p)} ÷ ${formatNumber(r)})`,result:formatValue(i,"A")},{formula:"V = √(P × R)",expression:`V = √(${formatNumber(p)} × ${formatNumber(r)})`,result:formatValue(v,"V")}]}return{voltage:v,current:i,resistance:r,power:p,conductance:1/r,steps:steps}};const relationRow=function(title,expressions){const rows=expressions.map(function(expression){return`<span>${escapeHtml(expression)}</span>`}).join("");return`<div class="ohmslaw-relation-row"><strong>${escapeHtml(title)}</strong><div>${rows}</div></div>`};const render=function($root,strings){const values={};let count=0;let invalid=false;$root.find(selectors.input).each(function(){const raw=$(this).val().trim();const key=$(this).data("value");if(raw===""){values[key]=null;return}const value=Number(raw);if(!Number.isFinite(value)||value<=0){invalid=true;values[key]=null;return}values[key]=value;count++});const $status=$root.find(selectors.status);const $results=$root.find(selectors.results);if(invalid){$status.text(strings.positive);$results.addClass("d-none");return}if(count<2){$status.text(strings.filltwo);$results.addClass("d-none");return}if(count>2){$status.text(strings.onlytwo);$results.addClass("d-none");return}const result=solve(values);if(![result.voltage,result.current,result.resistance,result.power].every(Number.isFinite)){$status.text(strings.invalidcombination);$results.addClass("d-none");return}$status.text(strings.calculated);$results.removeClass("d-none");Object.keys(units).forEach(function(key){$root.find(`[data-result='${key}']`).text(formatValue(result[key],units[key]))});const calculationHtml=result.steps.map(function(step,index){return`<div class="ohmslaw-step"><span class="ohmslaw-step-number">${index+1}</span><div><strong>${escapeHtml(step.formula)}</strong><div>${escapeHtml(step.expression)} = <b>${escapeHtml(step.result)}</b></div></div></div>`}).join("");$root.find(selectors.calculations).html(calculationHtml);const v=formatNumber(result.voltage);const i=formatNumber(result.current);const r=formatNumber(result.resistance);const p=formatNumber(result.power);const relations=[relationRow("Tensão (V)",[`V = R × I = ${r} × ${i} = ${v} V`,`V = P ÷ I = ${p} ÷ ${i} = ${v} V`,`V = √(P × R) = √(${p} × ${r}) = ${v} V`]),relationRow("Corrente (I)",[`I = V ÷ R = ${v} ÷ ${r} = ${i} A`,`I = P ÷ V = ${p} ÷ ${v} = ${i} A`,`I = √(P ÷ R) = √(${p} ÷ ${r}) = ${i} A`]),relationRow("Resistência (R)",[`R = V ÷ I = ${v} ÷ ${i} = ${r} Ω`,`R = V² ÷ P = ${v}² ÷ ${p} = ${r} Ω`,`R = P ÷ I² = ${p} ÷ ${i}² = ${r} Ω`]),relationRow("Potência (P)",[`P = V × I = ${v} × ${i} = ${p} W`,`P = I² × R = ${i}² × ${r} = ${p} W`,`P = V² ÷ R = ${v}² ÷ ${r} = ${p} W`])].join("");$root.find(selectors.relations).html(relations);const extras=[{label:strings.conductance,value:formatValue(result.conductance,"S"),detail:`G = 1 ÷ R = 1 ÷ ${r}`},{label:strings.powerflow,value:formatValue(result.power,"J/s"),detail:`1 W = 1 J/s`},{label:strings.milliamps,value:formatValue(result.current*1e3,"mA"),detail:`${i} A × 1000`},{label:strings.kiloohms,value:formatValue(result.resistance/1e3,"kΩ"),detail:`${r} Ω ÷ 1000`},{label:strings.milliwatts,value:formatValue(result.power*1e3,"mW"),detail:`${p} W × 1000`},{label:strings.kilowatts,value:formatValue(result.power/1e3,"kW"),detail:`${p} W ÷ 1000`}].map(function(item){return`<div class="ohmslaw-extra-card"><small>${escapeHtml(item.label)}</small><strong>${escapeHtml(item.value)}</strong><span>${escapeHtml(item.detail)}</span></div>`}).join("");$root.find(selectors.extras).html(extras)};const init=function(){const $root=$(selectors.root);if(!$root.length){return}Str.get_strings([{key:"filltwo",component:"mod_ohmslaw"},{key:"onlytwo",component:"mod_ohmslaw"},{key:"positive",component:"mod_ohmslaw"},{key:"invalidcombination",component:"mod_ohmslaw"},{key:"calculated",component:"mod_ohmslaw"},{key:"conductance",component:"mod_ohmslaw"},{key:"powerflow",component:"mod_ohmslaw"},{key:"milliamps",component:"mod_ohmslaw"},{key:"kiloohms",component:"mod_ohmslaw"},{key:"milliwatts",component:"mod_ohmslaw"},{key:"kilowatts",component:"mod_ohmslaw"}]).then(function(values){const keys=["filltwo","onlytwo","positive","invalidcombination","calculated","conductance","powerflow","milliamps","kiloohms","milliwatts","kilowatts"];const strings={};keys.forEach(function(key,index){strings[key]=values[index]});$root.on("input",selectors.input,function(){render($root,strings)});$root.on("click",selectors.clear,function(){$root.find(selectors.input).val("");render($root,strings);$root.find(selectors.input).first().trigger("focus")});render($root,strings);return strings}).catch(Notification.exception)};return{init:init}});